INSERT INTO public.editorial_sources (topic_id, article_id, title, url, publisher, excerpt, is_verified)
SELECT a.topic_id, a.id, s.title, s.url, s.publisher, s.excerpt, true
FROM source_rows s
JOIN public.editorial_articles a ON a.slug = s.slug
ON CONFLICT (article_id, url) DO UPDATE SET
  title = EXCLUDED.title, publisher = EXCLUDED.publisher, excerpt = EXCLUDED.excerpt,
  is_verified = true, retrieved_at = now();

